// @FIGURE_CODE_BEGIN
// ─ element spec ────────────────────────────────────────────────────────────
// torus            → TorusGeometry(a,b,26,96,arc) + MeshPhysicalMaterial grey glossy
// axis of rotation → CylinderGeometry(0.015,0.015,1) scaled, black
// centre dot       → SphereGeometry(0.07) black
// centroid path    → Line + LineDashedMaterial, red #E8413A, dash .12/gap .10
// path arrowheads  → ConeGeometry(0.075,0.2) red, far→+X, near→-X
// generating disk  → CircleGeometry(b,64) pale orange #F7D9A6, 0.75 opacity
// disk outline     → TorusGeometry(b,0.025,8,72) light blue #3FA9E0
// centroid dot     → SphereGeometry(0.06) red #E8413A
// dim arrow a      → cylinder shaft + 2 cones, black, 0 → a
// dim arrow b      → cylinder shaft + 2 cones, black, a → a+b
// labels a,b       → addLabel italic serif
// caption callout  → addLabel HTML box #F4DDB0 with pointer triangle

let A = 2.0, B = 0.6, tgtA = 2.0, tgtB = 0.6;
let progress = 1;          // sweep fraction (1 = full torus)
let playing = false, hold = 0;
let partState = 'all';

const root = new THREE.Group();
scene.add(root);

/* ── lights ─────────────────────────────────────────────────────────────── */
scene.add(new THREE.HemisphereLight(0xffffff, 0x8e8e96, 1.05));
const key = new THREE.DirectionalLight(0xffffff, 1.05); key.position.set(-5, 6, 5); scene.add(key);
const fill = new THREE.DirectionalLight(0xffffff, 0.35); fill.position.set(4, -2, 4); scene.add(fill);

/* ── materials ──────────────────────────────────────────────────────────── */
const blackMat = new THREE.MeshBasicMaterial({ color: 0x111111 });
const torusMat = new THREE.MeshPhysicalMaterial({
  color: 0xdcdce0, roughness: 0.34, metalness: 0.04,
  clearcoat: 0.75, clearcoatRoughness: 0.3,
  transparent: true, opacity: 1.0, side: THREE.DoubleSide
});
const redMat = new THREE.MeshBasicMaterial({ color: 0xE8413A });

/* ── torus ──────────────────────────────────────────────────────────────── */
const torus = new THREE.Mesh(new THREE.TorusGeometry(A, B, 26, 96), torusMat);
torus.rotation.x = Math.PI / 2;   // hole axis along +Y, torus angle u → world (R cos u,0,R sin u)
root.add(torus);

/* ── axis of revolution ─────────────────────────────────────────────────── */
const axis = new THREE.Mesh(new THREE.CylinderGeometry(0.016, 0.016, 1, 10), blackMat);
root.add(axis);
const centerDot = new THREE.Mesh(new THREE.SphereGeometry(0.07, 18, 14), blackMat);
root.add(centerDot);

/* ── centroid dashed path ───────────────────────────────────────────────── */
const pathMat = new THREE.LineDashedMaterial({ color: 0xE8413A, dashSize: 0.12, gapSize: 0.10 });
const pathLine = new THREE.Line(new THREE.BufferGeometry(), pathMat);
root.add(pathLine);

const headFar = new THREE.Mesh(new THREE.ConeGeometry(0.075, 0.21, 14), redMat);
headFar.rotation.z = -Math.PI / 2;                       // points +X
const headNear = new THREE.Mesh(new THREE.ConeGeometry(0.075, 0.21, 14), redMat);
headNear.rotation.z = Math.PI / 2;                       // points -X
root.add(headFar, headNear);

/* ── generating region (rotates with the sweep) ─────────────────────────── */
const genHolder = new THREE.Group();   // rotation.y = -t, sits at origin
root.add(genHolder);
const genGroup = new THREE.Group();    // translated to x = A along local +X
genHolder.add(genGroup);

const diskMat = new THREE.MeshBasicMaterial({
  color: 0xF7D9A6, transparent: true, opacity: 0.78, side: THREE.DoubleSide
});
const disk = new THREE.Mesh(new THREE.CircleGeometry(1, 64), diskMat);
genGroup.add(disk);
const ringMat = new THREE.MeshBasicMaterial({ color: 0x3FA9E0 });
const ring = new THREE.Mesh(new THREE.TorusGeometry(1, 0.026, 10, 80), ringMat);
genGroup.add(ring);
const centroidDot = new THREE.Mesh(new THREE.SphereGeometry(0.062, 16, 12), redMat);
genGroup.add(centroidDot);

/* ── dimension arrows (also ride the holder) ────────────────────────────── */
function makeDoubleArrow() {
  const g = new THREE.Group();
  const shaft = new THREE.Mesh(new THREE.CylinderGeometry(0.014, 0.014, 1, 8), blackMat);
  shaft.rotation.z = -Math.PI / 2;
  const h1 = new THREE.Mesh(new THREE.ConeGeometry(0.062, 0.18, 12), blackMat); h1.rotation.z = -Math.PI / 2;
  const h2 = new THREE.Mesh(new THREE.ConeGeometry(0.062, 0.18, 12), blackMat); h2.rotation.z = Math.PI / 2;
  g.add(shaft, h1, h2);
  g.setSpan = (x0, x1) => {
    const L = Math.max(x1 - x0, 0.001);
    shaft.position.x = (x0 + x1) / 2;
    shaft.scale.y = L;
    h1.position.x = x1 - 0.09;
    h2.position.x = x0 + 0.09;
  };
  return g;
