const dimA = makeDoubleArrow();
const dimB = makeDoubleArrow();
genHolder.add(dimA, dimB);

/* ── labels ─────────────────────────────────────────────────────────────── */
const SER = 'font-family:Georgia,\'Times New Roman\',serif;font-style:italic;font-size:18px';
const labA = addLabel(`<span style="${SER}">a</span>`, new THREE.Vector3(), { offset: [0, -14] });
const labB = addLabel(`<span style="${SER}">b</span>`, new THREE.Vector3(), { offset: [0, -14] });
const caption = addLabel(
