     <div style="position:absolute;top:-14px;left:10px;width:0;height:0;
          border-left:11px solid transparent;border-right:16px solid transparent;
          border-bottom:15px solid #F4DDB0"></div>
     The centroid travels<br>a distance 2&pi;<i style="font-family:Georgia,serif">a</i>.
   </div>`,
  new THREE.Vector3(1.0, -1.75, 2.1), { offset: [46, 34] });

/* ── interactive explanations ───────────────────────────────────────────── */
registerInteractive(torus, {
  title: 'The torus',
  tooltip: 'Solid of revolution',
  body: 'The solid swept out when the circular region of radius b revolves once about the vertical axis. Pappus: V = (distance travelled by the centroid) × (area of the region).'
});
registerInteractive(disk, {
  title: 'Generating region',
  tooltip: 'Plane region, area πb²',
  body: 'A plane circular region of radius b, standing perpendicular to its circular path. Its area is πb².'
});
registerInteractive(pathLine, {
  title: 'Centroid path',
  tooltip: 'Circle of radius a',
  body: 'The centroid (red dot) is a distance a from the axis, so in one full revolution it travels 2πa.'
});
registerInteractive(centerDot, {
  title: 'Axis of revolution',
  tooltip: 'The axis meets the mid-plane here',
  body: 'The vertical line about which the region revolves. It lies a units from the centroid, and a > b keeps the hole open.'
});

/* ── rebuild everything from A, B, progress ─────────────────────────────── */
const clampNote = document.getElementById('clampNote');
function rebuild() {
  const bMax = 0.9 * A;
  const clamped = B > bMax;
  const b = clamped ? bMax : B;
  clampNote.style.display = clamped ? '' : 'none';

  const t = progress * Math.PI * 2;

  // torus (partial during sweep)
  const arc = Math.max(0.0001, progress * Math.PI * 2);
  const tubSeg = Math.max(6, Math.round(96 * Math.max(progress, 0.06)));
  const g = new THREE.TorusGeometry(A, b, 26, tubSeg, arc);
  torus.geometry.dispose();
  torus.geometry = g;

  // axis
  const top = b + 1.9, bot = -(b + 1.5);
  axis.scale.y = top - bot;
  axis.position.y = (top + bot) / 2;

  // dashed centroid path
  const n = 220;
  const pts = [];
  const tEnd = Math.max(arc, 0.0001);
  for (let i = 0; i <= n; i++) {
    const u = tEnd * i / n;
    pts.push(new THREE.Vector3(A * Math.cos(u), 0, A * Math.sin(u)));
  }
  pathLine.geometry.dispose();
  pathLine.geometry = new THREE.BufferGeometry().setFromPoints(pts);
  pathLine.computeLineDistances();

  headFar.position.set(0, 0, -A);
  headNear.position.set(0, 0, A);

  // generating region
  genHolder.rotation.y = -t;
  genGroup.position.set(A, 0, 0);
  disk.scale.set(b, b, 1);
  ring.scale.set(b, b, 1);
  dimA.setSpan(0, A);
  dimB.setSpan(A, A + b);

  // labels follow the rotating holder: local (x,y,0) → (x cos t, y, x sin t)
  const ct = Math.cos(t), st = Math.sin(t);
  labA.pos.set(A * 0.5 * ct, 0.05, A * 0.5 * st);
  labB.pos.set((A + b * 0.5) * ct, 0.05, (A + b * 0.5) * st);

  updateFormulas(A, b);
  applyVisibility();
}

function updateFormulas(a, b) {
  const p = 2 * Math.PI * a, ar = Math.PI * b * b, pe = 2 * Math.PI * b;
  document.getElementById('aVal').textContent = a.toFixed(2);
  document.getElementById('bVal').textContent = B.toFixed(2);
  document.getElementById('fPath').textContent = p.toFixed(2);
  document.getElementById('fArea').textContent = ar.toFixed(2);
  document.getElementById('fPerim').textContent = pe.toFixed(2);
  document.getElementById('fVol').textContent = (p * ar).toFixed(2);
  document.getElementById('fSurf').textContent = (p * pe).toFixed(2);
}

/* ── visibility per Pappus component state ──────────────────────────────── */
function applyVisibility() {
  const S = partState;
  const showTorus = S !== 'generatingRegion';
  const ghost = (S === 'centroidPath' || S === 'radiusA');
  torus.visible = showTorus;
  torusMat.opacity = ghost ? 0.34 : 1.0;
  torusMat.depthWrite = !ghost;

  const showPath = (S === 'all' || S === 'centroidPath' || S === 'radiusA' || S === 'formulas');
  pathLine.visible = showPath;
  const full = progress >= 0.999;
  headFar.visible = headNear.visible = showPath && full;

  genGroup.visible = true;
  dimA.visible = (S === 'all' || S === 'radiusA' || S === 'formulas');
  dimB.visible = (S === 'all' || S === 'radiusB' || S === 'formulas');
  labA.div.style.visibility = dimA.visible ? 'visible' : 'hidden';
  labB.div.style.visibility = dimB.visible ? 'visible' : 'hidden';

  const showCap = (S === 'all' || S === 'centroidPath' || S === 'formulas');
  caption.div.style.visibility = showCap ? 'visible' : 'hidden';

  document.getElementById('formulaBox').style.boxShadow =
    (S === 'formulas') ? '0 0 0 2px #E8413A' : 'none';
}

