rebuild();
setCameraView({ projection: 'perspective', azimuthDeg: 90, elevationDeg: 28, rollDeg: 0, heightFraction: 0.62 });
controls.minPolarAngle = THREE.MathUtils.degToRad(10);
controls.maxPolarAngle = THREE.MathUtils.degToRad(80);
