/* ── update loop (tweening + sweep) ─────────────────────────────────────── */
let _last = performance.now();
function tick() {
  requestAnimationFrame(tick);
  const now = performance.now();
  const dt = Math.min(0.05, (now - _last) / 1000);
  _last = now;
  let dirty = false;

  if (Math.abs(A - tgtA) > 0.002) { A += (tgtA - A) * Math.min(1, dt * 6); dirty = true; }
  else if (A !== tgtA) { A = tgtA; dirty = true; }
  if (Math.abs(B - tgtB) > 0.002) { B += (tgtB - B) * Math.min(1, dt * 6); dirty = true; }
  else if (B !== tgtB) { B = tgtB; dirty = true; }
  if (dirty) { sA.value = A.toFixed(2); sB.value = B.toFixed(2); }

  if (playing) {
    if (hold > 0) { hold -= dt; if (hold <= 0) progress = 0; }
    else {
      progress += dt * 0.32;
      if (progress >= 1) { progress = 1; hold = 0.9; }
    }
    dirty = true;
  }
  if (dirty) rebuild();
}
tick();
