      const vars = opts.variables || ['t'];
      const material = new THREE.LineBasicMaterial({ color: opts.color ?? 0x1f77b4 });
      const line = new THREE.Line(new THREE.BufferGeometry(), material);
      scene.add(line);
      const handle = {
        id,
        object: line,
        fx: _resolveFn3d(opts.x ?? '0', vars),
        fy: _resolveFn3d(opts.y ?? '0', vars),
        fz: _resolveFn3d(opts.z ?? '0', vars),
        tDomain: opts.tDomain || [0, 1],
        samples: opts.samples || 200,
        setX(src) { this.fx = _resolveFn3d(src, vars); return this.sample(); },
        setY(src) { this.fy = _resolveFn3d(src, vars); return this.sample(); },
        setZ(src) { this.fz = _resolveFn3d(src, vars); return this.sample(); },
        remove() { scene.remove(line); _disposeObject(line); _plot3d.delete(id); },
        sample() {
          const [a, b] = this.tDomain;
          const n = Math.max(2, this.samples | 0);
          const pts = [];
          for (let i = 0; i < n; i++) {
            const t = a + (b - a) * (i / (n - 1));
            let x, y, z;
            try { x = this.fx(t); y = this.fy(t); z = this.fz(t); } catch { x = y = z = NaN; }
