  const arc = Math.max(0.0001, progress * Math.PI * 2);
  const tubSeg = Math.max(8, Math.round(96 * Math.max(progress, 0.08)));
  const g = new THREE.TorusGeometry(A, b, 28, tubSeg, arc);
  torus.geometry.dispose();
  torus.geometry = g;

  // axis: proportions matched to the source (≈ ±1.8 for a = 2, b = 0.6)
  const top = b + 1.2, bot = -(b + 1.1);
  axis.scale.y = top - bot;
  axis.position.y = (top + bot) / 2;

  // dashed centroid path
  const n = 240;
  const pts = [];
  const tEnd = Math.max(arc, 0.0001);
  for (let i = 0; i <= n; i++) {
    const u = tEnd * i / n;
    pts.push(new THREE.Vector3(A * Math.cos(u), 0, A * Math.sin(u)));
  }
  pathLine.geometry.dispose();
  pathLine.geometry = new THREE.BufferGeometry().setFromPoints(pts);
  pathLine.computeLineDistances();

  headFar.position.set(0, 0, -A);
  headNear.position.set(0, 0, A);

  // generating region
  genHolder.rotation.y = -t;
  genGroup.position.set(A, 0, 0);
  disk.scale.set(b, b, 1);
  if (Math.abs(b - ringB) > 0.001) {
    ring.geometry.dispose();
    ring.geometry = new THREE.TorusGeometry(b, 0.032, 10, 90);
    ringB = b;
  }
  // while sweeping, let the fresh tube occlude the disk; static view draws it on top
  diskMat.depthTest = ringMat.depthTest = redTopMat.depthTest = full;
  diskMat.depthTest = !full ? true : false;
  ringMat.depthTest = !full ? true : false;
  redTopMat.depthTest = !full ? true : false;

  dimA.setSpan(0, A);
  dimB.setSpan(A, A + b);

  // labels follow the rotating holder: local (x,y,0) → (x cos t, y, x sin t)
  const ct = Math.cos(t), st = Math.sin(t);
  labA.pos.set(A * 0.5 * ct, 0.06, A * 0.5 * st);
  labB.pos.set((A + b * 0.5) * ct, 0.06, (A + b * 0.5) * st);

  updateFormulas(A, b);
  applyVisibility();
}

function updateFormulas(a, b) {
  const p = 2 * Math.PI * a, ar = Math.PI * b * b, pe = 2 * Math.PI * b;
  document.getElementById('aVal').textContent = a.toFixed(2);
  document.getElementById('bVal').textContent = b.toFixed(2);
  document.getElementById('fPath').textContent = p.toFixed(2);
  document.getElementById('fArea').textContent = ar.toFixed(2);
  document.getElementById('fPerim').textContent = pe.toFixed(2);
  document.getElementById('fVol').textContent = (p * ar).toFixed(2);
  document.getElementById('fSurf').textContent = (p * pe).toFixed(2);
}

/* ── visibility per Pappus component state ──────────────────────────────── */
function applyVisibility() {
  const S = partState;
  const showTorus = S !== 'generatingRegion';
  const ghost = (S === 'centroidPath' || S === 'radiusA');
  torus.visible = showTorus;
  torusMat.opacity = ghost ? 0.32 : 1.0;
  torusMat.depthWrite = !ghost;

  const showPath = (S === 'all' || S === 'centroidPath' || S === 'radiusA' || S === 'formulas');
  pathLine.visible = showPath;
  const full = progress >= 0.999;
  headFar.visible = headNear.visible = showPath && full;

  genGroup.visible = true;
  dimA.visible = (S === 'all' || S === 'radiusA' || S === 'formulas');
  dimB.visible = (S === 'all' || S === 'radiusB' || S === 'formulas');
  labA.div.style.visibility = dimA.visible ? 'visible' : 'hidden';
  labB.div.style.visibility = dimB.visible ? 'visible' : 'hidden';

  const showCap = (S === 'all' || S === 'centroidPath' || S === 'formulas');
  caption.div.style.visibility = showCap ? 'visible' : 'hidden';

  document.getElementById('formulaBox').style.boxShadow =
    (S === 'formulas') ? '0 0 0 2px #E8413A' : 'none';
}

/* ── initial build + camera ─────────────────────────────────────────────── */
rebuild();
setCameraView({ projection: 'perspective', azimuthDeg: 90, elevationDeg: 28, rollDeg: 0, heightFraction: 0.74 });
controls.minPolarAngle = THREE.MathUtils.degToRad(10);
controls.maxPolarAngle = THREE.MathUtils.degToRad(80);
document.getElementById('btnReset').style.display = '';

/* ── controls ───────────────────────────────────────────────────────────── */
const sA = document.getElementById('majorRadius');
const sB = document.getElementById('tubeRadius');
sA.addEventListener('input', () => { tgtA = A = parseFloat(sA.value); rebuild(); });
sB.addEventListener('input', () => { tgtB = B = parseFloat(sB.value); rebuild(); });

const btnSweep = document.getElementById('btnSweep');
function stopSweep() {
  playing = false; hold = 0; progress = 1;
  btnSweep.textContent = '▶ Revolve generating circle';
  btnSweep.classList.remove('active');
}
function startSweep() {
  playing = true; progress = 0; hold = 0;
  btnSweep.textContent = '■ Stop revolution';
  btnSweep.classList.add('active');
}
btnSweep.addEventListener('click', () => { playing ? stopSweep() : startSweep(); rebuild(); });

const stateBtns = [...document.querySelectorAll('#stateBtns button')];
function setPart(s) {
  partState = s;
  stateBtns.forEach(b => b.classList.toggle('active', b.dataset.state === s));
  applyVisibility();
}
stateBtns.forEach(b => b.addEventListener('click', () => setPart(b.dataset.state)));

/* ── guided demo steps ──────────────────────────────────────────────────── */
const STEPS = [
  { title: 'The figure as drawn', narration: 'A torus with its vertical axis of revolution; the red dashed circle is the path of the centroid at distance a, and the blue circle of radius b is the region being revolved.', state: { pappusParts: 'all', majorRadius: 2, tubeRadius: 0.6, play: false } },
  { title: 'The revolving region', narration: 'Only the pale orange disk of radius b remains: a plane region of area πb² standing perpendicular to the path.', state: { pappusParts: 'generatingRegion', play: false } },
  { title: 'Sweeping out the solid', narration: 'The disk turns a full 360° about the axis and its centroid traces a circle of circumference 2πa.', state: { pappusParts: 'centroidPath', play: true } },
  { title: 'Reading off a and b', narration: 'The double arrow from the axis to the red centroid is a; the short arrow from centroid to rim is b. Change a and watch the hole open up.', state: { pappusParts: 'radiusA', majorRadius: 2.6, tubeRadius: 0.6, play: false } },
  { title: 'Fatten the tube', narration: 'Increasing b enlarges the cross-sectional area πb²; volume responds quadratically while surface area responds only linearly.', state: { pappusParts: 'radiusB', majorRadius: 2, tubeRadius: 0.9, play: false } },
  { title: "Pappus' Theorem", narration: 'Multiply the travel distance by the area: V = (2πa)(πb²) = 2π²ab², and by the perimeter for S = 4π²ab.', state: { pappusParts: 'formulas', majorRadius: 2, tubeRadius: 0.6, play: false } }
];
let stepIdx = 0;
function goToStep(i) {
  stepIdx = (i + STEPS.length) % STEPS.length;
  const s = STEPS[stepIdx];
  document.getElementById('stepTitle').textContent = (stepIdx + 1) + '. ' + s.title;
  document.getElementById('stepText').textContent = s.narration;
  if (s.state.majorRadius !== undefined) { tgtA = s.state.majorRadius; sA.value = tgtA; }
  if (s.state.tubeRadius !== undefined) { tgtB = s.state.tubeRadius; sB.value = tgtB; }
  if (s.state.pappusParts) setPart(s.state.pappusParts);
  if (s.state.play && !playing) startSweep();
  else if (s.state.play === false && playing) stopSweep();
  rebuild();
}
document.getElementById('btnPrev').addEventListener('click', () => goToStep(stepIdx - 1));
document.getElementById('btnNext').addEventListener('click', () => goToStep(stepIdx + 1));
goToStep(0);

/* ── keep label text at a constant on-screen size ───────────────────────── */
function relabel() {
  for (const e of _mLabels) {
    let s;
    if (camera.isOrthographicCamera) {
      const ref = (typeof _labelZoomRef === 'number' && _labelZoomRef) ? _labelZoomRef : 1;
      s = (camera.zoom || 1) / ref;
    } else {
      s = 8 / Math.max(camera.position.distanceTo(e.pos), 1e-4);
    }
    s = Math.max(0.15, Math.min(s, 6));
    e.div.style.fontSize = (e.px / s).toFixed(2) + 'px';
  }
}

/* ── update loop (tweening + sweep) ─────────────────────────────────────── */
let _last = performance.now();
function tick() {
  requestAnimationFrame(tick);
  const now = performance.now();
  const dt = Math.min(0.05, (now - _last) / 1000);
  _last = now;
  let dirty = false;

  if (Math.abs(A - tgtA) > 0.002) { A += (tgtA - A) * Math.min(1, dt * 6); dirty = true; }
  else if (A !== tgtA) { A = tgtA; dirty = true; }
  if (Math.abs(B - tgtB) > 0.002) { B += (tgtB - B) * Math.min(1, dt * 6); dirty = true; }
  else if (B !== tgtB) { B = tgtB; dirty = true; }
  if (dirty) { sA.value = A.toFixed(2); sB.value = B.toFixed(2); }

  if (playing) {
    if (hold > 0) { hold -= dt; if (hold <= 0) progress = 0; }
    else {
      progress += dt * 0.32;
      if (progress >= 1) { progress = 1; hold = 0.9; }
    }
    dirty = true;
  }
  if (dirty) rebuild();
  relabel();
}
tick();
// @FIGURE_CODE_END

Fix all identified failure modes and improve every score. Maintain or improve what already works well.
Return ONLY the updated marker-wrapped payload.

