// @FIGURE_CODE_BEGIN
// ─ element spec ────────────────────────────────────────────────────────────
// torus             → TorusGeometry(a,b,32,96,arc), rot.x=π/2, MeshPhysicalMaterial near-white glossy grey
// axis of rotation  → CylinderGeometry(0.018,0.018,L) black, depth-tested (near tube hides it)
// centre dot        → SphereGeometry(0.085) black, overlay (depthTest/Write off)
// centroid path     → Line + LineDashedMaterial red #E8413A dash .12/gap .10, overlay
// path arrowheads   → ConeGeometry(0.11,0.32) red overlay: far(-Z)→+X, near(+Z)→-X
// generating disk   → CircleGeometry(b,64) pale orange #F7D9A6 0.78, faces viewer, overlay
// disk outline      → TorusGeometry(b,0.05,12,110) light blue #3FA9E0, overlay above disk
// centroid dot      → SphereGeometry(0.095) red #E8413A, overlay above disk
// dim arrow a       → cylinder shaft(r .024) + 2 cones black overlay, 0 → a
// dim arrow b       → cylinder shaft(r .024) + 2 cones black overlay, a → a+b
// labels a,b        → addLabel italic serif ≈30px, on the arrows
// caption callout   → addLabel HTML box #F4DDB0 + SVG fat arrow pointing up-left, ≈19px

let A = 2.0, B = 0.6, tgtA = 2.0, tgtB = 0.6;
let progress = 1;          // sweep fraction (1 = full torus)
let playing = false, hold = 0;
let partState = 'all';
let ringB = -1;

const root = new THREE.Group();
scene.add(root);

/* ── lights (soft, bright: near-white glossy grey like the print) ───────── */
scene.add(new THREE.HemisphereLight(0xffffff, 0xc6c7cd, 0.95));
const key = new THREE.DirectionalLight(0xffffff, 0.62); key.position.set(-5, 6, 5); scene.add(key);
const fill = new THREE.DirectionalLight(0xffffff, 0.32); fill.position.set(4, -1, 5); scene.add(fill);
const rim = new THREE.DirectionalLight(0xffffff, 0.16); rim.position.set(2, 4, -6); scene.add(rim);

/* ── materials ──────────────────────────────────────────────────────────── */
// overlay material: always drawn on top of the shaded solid, never occluded
function overlayMat(color, opacity) {
  return new THREE.MeshBasicMaterial({
    color, transparent: true, opacity: (opacity === undefined ? 1 : opacity),
    depthTest: false, depthWrite: false, side: THREE.DoubleSide
  });
}
const blackMat = new THREE.MeshBasicMaterial({ color: 0x111111 });     // depth-tested axis
const arrowMat = overlayMat(0x111111);
const redMat = overlayMat(0xE8413A);
const diskMat = overlayMat(0xF7D9A6, 0.78);
const ringMat = overlayMat(0x3FA9E0);

const torusMat = new THREE.MeshPhysicalMaterial({
  color: 0xf3f3f5, roughness: 0.46, metalness: 0.0,
  clearcoat: 0.45, clearcoatRoughness: 0.55,
  specularIntensity: 0.35,
  transparent: false, opacity: 1.0, side: THREE.DoubleSide
});

/* ── torus ──────────────────────────────────────────────────────────────── */
const torus = new THREE.Mesh(new THREE.TorusGeometry(A, B, 32, 96), torusMat);
torus.rotation.x = Math.PI / 2;   // hole axis along +Y
torus.renderOrder = 0;
root.add(torus);

/* ── axis of revolution (occluded by the near tube, as in the source) ───── */
const axis = new THREE.Mesh(new THREE.CylinderGeometry(0.018, 0.018, 1, 12), blackMat);
root.add(axis);
const centerDot = new THREE.Mesh(new THREE.SphereGeometry(0.085, 20, 16), arrowMat);
centerDot.renderOrder = 30;
root.add(centerDot);

/* ── centroid dashed path (drawn over the torus, like the printed figure) ─ */
const pathMat = new THREE.LineDashedMaterial({
  color: 0xE8413A, dashSize: 0.12, gapSize: 0.10,
  depthTest: false, depthWrite: false, transparent: true, linewidth: 2
});
const pathLine = new THREE.Line(new THREE.BufferGeometry(), pathMat);
pathLine.renderOrder = 20;
root.add(pathLine);

