/* ── dimension arrows (ride the rotating holder) ────────────────────────── */
function makeDoubleArrow(shaftR) {
  const g = new THREE.Group();
  const shaft = new THREE.Mesh(new THREE.CylinderGeometry(shaftR, shaftR, 1, 12), arrowMat);
  shaft.rotation.z = -Math.PI / 2;
  const h1 = new THREE.Mesh(new THREE.ConeGeometry(1, 1, 18), arrowMat); h1.rotation.z = -Math.PI / 2;
  const h2 = new THREE.Mesh(new THREE.ConeGeometry(1, 1, 18), arrowMat); h2.rotation.z = Math.PI / 2;
  shaft.renderOrder = h1.renderOrder = h2.renderOrder = 28;
  g.add(shaft, h1, h2);
  g.setSpan = (x0, x1) => {
    const L = Math.max(x1 - x0, 0.001);
    const hl = Math.min(0.28, L * 0.5);      // head length
    const hr = Math.min(0.105, L * 0.3);     // head radius
    shaft.position.x = (x0 + x1) / 2;
    shaft.scale.y = L;
    h1.scale.set(hr, hl, hr); h1.position.x = x1 - hl / 2;
    h2.scale.set(hr, hl, hr); h2.position.x = x0 + hl / 2;
  };
  return g;
}
const dimA = makeDoubleArrow(0.024);
const dimB = makeDoubleArrow(0.024);
